public class SuperStatement : IbcError
{
    public SuperStatementRow[] Rows;

    public static SuperStatement GetReport(int custId)
    {
        SuperStatement report = new SuperStatement();
        report.ErrorCode = IbcError.SUCCESS;
        report.ErrorMsg = IbcError.SUCCESS_MSG;
        Hashtable param = new Hashtable();
        param.Add("custid", custId);
        try
        {
            using (IDataReader dr = DataServices.ExecuteReader("Rpt_SuperAgentStatement", param, DatabaseType.ARCHIVE))
            {
                if (dr == null)
                {
                    report.ErrorCode = IbcError.INTERNAL_ERROR;
                    report.ErrorMsg = IbcError.INTERNAL_ERROR_MSG;
                }
                else
                {
                    List<SuperStatementRow> reportRow = new List<SuperStatementRow>();
                    double total = 0;
                    while (dr.Read())
                    {
                        SuperStatementRow row = new SuperStatementRow();
                        row.Date = dr["matchdate"].ToString();
                        row.Type = dr["transtype"].ToString();
                        row.Remark = dr["transdesc"].ToString();
                        row.TotalAmount = FormatHandler.GetDouble(dr["totalamt"],2);
                        row.Total = total + row.TotalAmount;

                        row.Total = FormatHandler.GetDouble(row.Total, 2);

                        reportRow.Add(row);
                    }// end while
                    report.Rows = reportRow.ToArray();
                    report.ErrorCode = IbcError.SUCCESS;
                    report.ErrorMsg = IbcError.SUCCESS_MSG;
                }// end if(dr== null)
            }// end using
        }
        catch
        {
            report.ErrorCode = IbcError.INTERNAL_ERROR;
            report.ErrorMsg = IbcError.INTERNAL_ERROR_MSG;
        }
        return report;
    }
}